import json;r=json.load(open('results/analysis/falcon/summary.json'))
for k,v in r.items():
    if k.startswith(('battery','pair','matched','H3','FNR_by_variant','FNR_by_in')) : print(k, json.dumps(v))
print(json.dumps(r['per_metric_FNR']));print(json.dumps(r['per_metric_FPR']));print(r['n_sensitivity'])"

